import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Transaksi> trx = Arrays.asList(
                new Transaksi("Sari", "Kopi Susu", 2, 18000),
                new Transaksi("Budi", "Teh Manis", 3, 8000),
                new Transaksi("Sari", "Roti Bakar", 1, 15000),
                new Transaksi("Budi", "Kopi Susu", 1, 18000),
                new Transaksi("Sari", "Teh Manis", 2, 8000));

        int omzet = trx.stream().mapToInt(Transaksi::getTotal).sum();
        System.out.println("Omzet: " + omzet);

        Map<String, Integer> perKasir = trx.stream()
                .collect(Collectors.groupingBy(Transaksi::getKasir, TreeMap::new,
                        Collectors.summingInt(Transaksi::getTotal)));
        System.out.println("Per kasir: " + perKasir);

        Map<String, Integer> terjual = trx.stream()
                .collect(Collectors.groupingBy(Transaksi::getMenu, TreeMap::new,
                        Collectors.summingInt(Transaksi::getJumlah)));
        System.out.println("Terjual: " + terjual);

        boolean adaBesar = trx.stream().anyMatch(t -> t.getTotal() >= 30000);
        System.out.println("Ada transaksi >= 30000: " + adaBesar);
    }
}

class Transaksi {
    private String kasir;
    private String menu;
    private int jumlah;
    private int harga;

    Transaksi(String kasir, String menu, int jumlah, int harga) {
        this.kasir = kasir;
        this.menu = menu;
        this.jumlah = jumlah;
        this.harga = harga;
    }

    String getKasir() {
        return kasir;
    }

    String getMenu() {
        return menu;
    }

    int getJumlah() {
        return jumlah;
    }

    int getTotal() {
        return jumlah * harga;
    }
}

